using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class NavigationFlowTests {
  GameRuntime game;string save;const string Output="/tmp/idle-navigation-review";
  [UnitySetUp]public IEnumerator Setup(){Directory.CreateDirectory(Output);save=Path.Combine(Path.GetTempPath(),"idle-nav-"+Guid.NewGuid(),"save.json");Directory.CreateDirectory(Path.GetDirectoryName(save));GameRuntime.SavePathOverride=save;yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<8;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));PortraitGameView.Set(390,846);yield return null;}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  void Ready(){game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Credits=n.Data=ScientificNumber.From(1e9);n.Prestige.resets=1;n.Prestige.Total=n.Prestige.Free=n.Prestige.Cycle=n.Prestige.Entitlement=ScientificNumber.One;n.Workshop.components=Enumerable.Repeat(1000L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.learned=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.starterGift=true;n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.tutorial="skipped";return n;});}
  Button[] Bottom()=>game.HardwareTab.transform.parent.GetComponentsInChildren<Button>();
  [UnityTest]public IEnumerator RealRoutesUnlocksResearchAndReload(){yield return null;Assert.That(Bottom().Length,Is.EqualTo(4));Assert.That(game.TrainingTab.gameObject.activeSelf,Is.False);Assert.That(game.PrestigeTab.gameObject.activeSelf,Is.False);game.GetComponent<MobileShell>().Laboratory.ModelButton.onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("training"));Assert.That(GameObject.Find("training-quality"),Is.Not.Null);game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Data=ScientificNumber.From(10000);return n;});game.ResearchTab.onClick.Invoke();yield return null;var research=GameObject.Find("research-dataGeneration").GetComponent<LearningCard>();Assert.That(research.Effect.gameObject.activeSelf,Is.False);research.Card.Button.onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("details"));Assert.That(game.State.ResearchJob,Is.Null);GameObject.Find("CloseEconomyDetail").GetComponent<Button>().onClick.Invoke();yield return null;research=GameObject.Find("research-dataGeneration").GetComponent<LearningCard>();research.StartAction.onClick.Invoke();Assert.That(game.State.ResearchJob,Is.Not.Null,"Research start from compact card must commit");yield return new WaitForSecondsRealtime(.15f);Assert.That(GameObject.Find("LabSlot0/Status").GetComponent<Text>().text,Does.Contain("s"));Assert.That(GameObject.Find("SecretLab"),Is.Null);Ready();yield return null;Assert.That(Bottom().Length,Is.EqualTo(5));Assert.That(game.PrestigeTab.GetComponentInChildren<Text>().text,Is.EqualTo("Prestige"));game.PrestigeTab.onClick.Invoke();yield return null;Assert.That(GameObject.Find("NetworkLayer"),Is.Null,"Axioms must remain absent before their unlock");game.ItemsTab.onClick.Invoke();yield return null;Assert.That(game.WorkshopView.Mode,Is.EqualTo("inventory"));foreach(string mode in new[]{"components","blueprints","craft","fusion","inventory"}){game.WorkshopView.ChangeMode(mode);yield return null;Assert.That(game.WorkshopView.Mode,Is.EqualTo(mode));}game.GetComponent<MobileShell>().ShopTab.onClick.Invoke();yield return null;Assert.That(GameObject.Find("Shop-market"),Is.Not.Null);GameObject.Find("Shop-market").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("market"));var loaded=new AtomicSaveStore(save,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True);Assert.That(loaded.State.ResearchJob,Is.Not.Null);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();yield return null;Assert.That(Bottom().Length,Is.EqualTo(5));Assert.That(game.State.ResearchJob,Is.Not.Null);}
  [UnityTest]public IEnumerator FeedbackStaysBoundedAndLabSlotsKeepTheirIdentity(){Ready();game.Audio.Unlock();var sources=game.GetComponents<AudioSource>();foreach(var id in new[]{"forge-impact","fusion-impact","gumball-turn","gumball-open","unlock","forge-impact"})Assert.That(game.Audio.Play(id),Is.True,id);Assert.That(game.GetComponents<AudioSource>().Length,Is.EqualTo(sources.Length));game.Act(s=>{var n=s.Copy();n.Upgrades.purchasedLabs=2;n=Game.Research(n,"dataGeneration").Copy();n.ResearchJob.slot=2;return n;});game.Show("research");yield return new WaitForSecondsRealtime(.2f);Assert.That(GameObject.Find("LabSlot0/Status").GetComponent<Text>().text,Does.Contain("Frei").Or.Contain("Available"));Assert.That(GameObject.Find("LabSlot2/Status").GetComponent<Text>().text,Does.Contain("s"));WorkshopTests.Capture(390,846,Output+"/research-three-labs.png");game.Act(s=>{var n=s.Copy();n.Upgrades.purchasedLabs=0;return n;});Assert.That(game.Writable,Is.True);yield return new WaitForSecondsRealtime(.2f);Assert.That(GameObject.Find("LabSlot2/Status"),Is.Not.Null,"Retained paid work stays visible after lab capacity shrinks");Assert.That(GameObject.Find("LabSlot1"),Is.Null);Assert.That(GameObject.Find("LabSlot2/Status").GetComponent<Text>().text,Does.Contain("Finishing").Or.Contain("Abschluss"));WorkshopTests.Capture(390,846,Output+"/research-retained-lab.png");yield return null;}
  [UnityTest]public IEnumerator BlueprintDetailLearnsOnceAndOpensCrafting(){Ready();var definition=ItemBalance.Items.Where(d=>d.BlueprintPrice>0&&d.Access!="lab"&&d.Access!="axiom"&&d.Access!="model-set").OrderBy(d=>d.BlueprintPrice).First();int index=Workshop.Index(definition.Id);game.Act(s=>{var n=s.Copy();n.Workshop.fragments=10000;n.Workshop.learned[index]=false;n.Research[Game.ResearchIndex("blueprints")]=1;return n;});game.ItemsTab.onClick.Invoke();yield return null;GameObject.Find("Blueprints").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(game.WorkshopView.ForgePanel.activeSelf,Is.False);GameObject.Find("recipe-"+definition.Id).GetComponent<ActionCard>().Button.onClick.Invoke();yield return null;var learn=GameObject.Find("LearnBlueprint").GetComponent<Button>();Assert.That(learn.interactable,Is.True);long before=game.State.Workshop.fragments;learn.onClick.Invoke();Assert.That(game.State.Workshop.learned[index],Is.True);Assert.That(game.State.Workshop.fragments,Is.EqualTo(before-definition.BlueprintPrice));yield return null;GameObject.Find("LearnBlueprint").GetComponent<Button>().onClick.Invoke();Assert.That(game.WorkshopView.Mode,Is.EqualTo("craft"));Assert.That(game.WorkshopView.ForgePanel.activeSelf,Is.True);Assert.That(new AtomicSaveStore(save,new UnitySaveCodec()).Load(game.State.SavedAt).State.Workshop.learned[index],Is.True);}
  [UnityTest]public IEnumerator CaptureConnectedViewsAtMobileSizes(){Ready();foreach(string language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));foreach(int width in new[]{320,390,430}){PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;foreach(string route in new[]{"hardware","research","items","shop"}){game.Show(route);if(route=="items")game.WorkshopView.ChangeMode("inventory");yield return null;yield return null;Canvas.ForceUpdateCanvases();yield return new WaitForSecondsRealtime(.4f);foreach(var b in Bottom())Assert.That(((RectTransform)b.transform).rect.width,Is.GreaterThanOrEqualTo(44));WorkshopTests.Capture(width,Screen.height,Output+"/"+route+"-"+language+"-"+width+".png");}game.Show("items");foreach(string mode in new[]{"components","blueprints","craft","fusion"}){game.WorkshopView.ChangeMode(mode);yield return null;yield return null;Canvas.ForceUpdateCanvases();yield return new WaitForSecondsRealtime(.4f);WorkshopTests.Capture(width,Screen.height,Output+"/"+mode+"-"+language+"-"+width+".png");}}}}
  [UnityTest]public IEnumerator RecordSavedCraftAndFusionThroughTabs(){Ready();game.Audio.Unlock();game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;GameObject.Find("Crafting").GetComponent<Button>().onClick.Invoke();ui.SelectRecipe(Workshop.Index("quantum-chip"));yield return null;var node=new GameObject("ReviewAudio",typeof(AudioListener),typeof(ReviewAudioCapture));var previous=UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Where(a=>a.gameObject!=node).ToArray();foreach(var a in previous)a.enabled=false;var audio=node.GetComponent<ReviewAudioCapture>();audio.Begin();var times=new List<string>();string folder=Output+"/motion";Directory.CreateDirectory(folder);int frame=0;double start=Time.realtimeSinceStartupAsDouble;bool crafted=false,fused=false,selected=false;while(Time.realtimeSinceStartupAsDouble-start<9){double t=Time.realtimeSinceStartupAsDouble-start;if(t>=.7&&!crafted){crafted=true;ui.Commit();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));}if(t>=4&&!selected){selected=true;ui.Commit();ui.Commit();ui.Forge.Cancel();GameObject.Find("FusionMode").GetComponent<Button>().onClick.Invoke();foreach(var item in game.State.Workshop.inventory.ToArray())ui.ToggleSelection(item.id);}if(t>=5&&!fused){fused=true;ui.Commit();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(game.State.Workshop.inventory[0].rarity,Is.EqualTo(1));}times.Add(t.ToString("R",System.Globalization.CultureInfo.InvariantCulture));WorkshopTests.Capture(390,846,folder+"/"+(frame++).ToString("D4")+".png");yield return null;}audio.Save(folder);foreach(var a in previous)if(a!=null)a.enabled=true;UnityEngine.Object.Destroy(node);File.WriteAllLines(folder+"/times.txt",times);Assert.That(ui.Forge.IsAnimating,Is.False);var read=new AtomicSaveStore(save,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(read.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(read.State.Workshop.inventory[0].rarity,Is.EqualTo(1));}
 }
}
